import {MfeInitFunctionConfig} from '../interfaces';

export function validateMfeInitConfig(config: MfeInitFunctionConfig): MfeInitFunctionConfig {

  const element = config.element;
  delete (config as any).element;

  try {
    return {
      element: element,
      // This is indeed doing something useful. It's ensuring that developers are passing information
      // with the MfeInitFunctionConfig properly.
      // 1) It's ensuring that we are getting data that can be turned into a JSON string
      // 2) It removes any functions that the config object was previously pointing at.
      ...JSON.parse(JSON.stringify(config))
    };

  } catch (e) {
    console.error('The config object is not valid. It could not be serialized and then deserialized. Please fix.');
    return config;
  }
}